custom_css:
/* Chat Window(黑白) v1.1 2025-10-22
主题作者：咩野(DC@lambkinling)
请勿二传，二改请标源，倒卖、商用引流司马;
部分代码来自：KAKAA老师的双色盒子、NARIKI、babylon，特此感谢。 */

/* 字体颜色在酒馆自带调色盘里调整，下划线文本颜色→对话&引用文本的背景色 */

/* === 0. 变量定义 === */
:root {
  --主色调: #000;
  --辅助色: #fff;
  --背景色: rgba(255, 255,  255, 0.25);
  --阴影: rgba(0, 0, 0, 0.25);
  --模糊程度: 10px;
  --圆角: 0px;
  --名字左右: 110px;
  --名字上下: -95px;
  --名字大小: 1.2;
  --字体大小: calc(var(--mainFontSize) * 0.85);
  --三元素大小: calc(var(--mainFontSize) * 0.95);
}

/* === 1. 文本样式 === */
/* 斜体 */
em {
    text-decoration: 0.05em underline solid var(--SmartThemeEmColor);
    text-underline-offset: 2.5px;
}

/* 对话 */
q {
    background: var(--SmartThemeUnderlineColor);
    border-radius: 1px;
    padding: 0 2px;
}

/* 删除 */
del {
  color: red;
}

/* 代码块 */
code {
    background: var(--主色调);
    border: none;
    border-radius: 0;
    box-shadow: 0.5px 0.5px 2px var(--辅助色);
}

.mes pre code {
    position: relative;
    background: linear-gradient(to bottom, var(--主色调) 25px, var(--辅助色) 25px);
    border-radius: 0;
    border: none;
    box-shadow: 1px 1px 3px var(--阴影);
    padding-top: 35px;
    padding-bottom: 35px;
    &::before {
        content:"我已知晓";
        position: absolute;
        font-size: calc(var(--mainFontSize) * 0.85);
        background: green;
        color: var(--辅助色);
        padding: 0 5px;
        bottom: 8px;
        right: 10px;
    }
}

/* 代码块内文字 */
.hljs {
  color: var(--SmartThemeBodyColor);
  font-size: var(--mainFontSize) !important;
  line-height: 1.6;
}

/* md标题 */
.hljs-section {
  color: var(--SmartThemeEmColor) !important;
}

/* md粗体 */
.hljs-strong {
  color: var(--SmartThemeQuoteColor) !important;
}

/* --- md引用文本 --- */
blockquote {
    border-color: var(--主色调) !important;
    background: 
        linear-gradient(to right,
            var(--SmartThemeUnderlineColor),
            transparent) !important;
}

/* ===== 2. 滚动条 & 滑动条 ===== */
/* --- 滚动条 --- */
#chat::-webkit-scrollbar {
    display: none;
}

::-webkit-scrollbar {
    width: 4px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background: var(--主色调) !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: none !important;
}

/* iOS 兼容性 */
body {
    -webkit-overflow-scrolling: touch;
}

/* --- 滑动条 --- */
input[type="range"] {
    background-color: var(--主色调) !important;
    border-radius: 0 !important;
    height: 2px !important;
    filter: none !important;
    box-shadow: none !important;
}

input[type="range"]::-webkit-slider-thumb {
    background: var(--主色调) !important;
    border-radius: 0;
    outline: 1px solid var(--辅助色);
    outline-offset: -2px;
    transform: scale(0.78) rotate(45deg);
    filter: none !important;
    box-shadow: none !important;
}

/* ===== 3. 聊天区域 ===== */
#chat {
  background: none;
  border: none;
  scrollbar-width: none;
}

/* --- 欢迎页 --- */
.welcomePanel .recentChatList .recentChat {
    margin-bottom: 3px;
    border-radius: 0;
    background: var(--背景色);
    -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
    backdrop-filter: blur(var(--模糊程度)) !important;
    box-shadow: 2px 2px 0 1px var(--主色调) !important;
}

/* --- 思维链 --- */
.mes_reasoning_header {
    padding: 2px 10px;
    margin: 10px auto 0;
    border-top: 1px solid var(--主色调);
    border-bottom: 1px solid var(--主色调);
    border-radius: 0;
    background-color: transparent;
    box-shadow: 0 1px px var(--阴影) !important;
}

/* 🐕思维链 - 自定义文案 */
.mes_reasoning_header_title::before {
  content: "404 Not Found";
  white-space: nowrap;
  font-size: calc(var(--mainFontSize) * 0.85);
  color: var(--SmartThemeBodyColor);
}

.mes_reasoning_header_title {
  font-size: 0;
}
.mes_reasoning_arrow {
  display: none;
}

.mes_reasoning {
  max-height: 550px; /* 思维链内容高度 */
  overflow: hidden auto;
  font-size: calc(var(--mainFontSize) * 0.9);
  background: rgba(255, 255, 255, 0.65);
}

/* 消息区域 */
body .mes {
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 96%; /* 🐕宽度 */
  margin: 20px auto;
  padding: 5px;
  background: rgba(255, 255, 255, 0.05);
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
  border-radius: var(--圆角) !important;
}

/* 最后一条信息高度 */
.last_mes {
  margin-bottom: 80px !important;
}

body .mes_block {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    overflow: visible;
    padding: 0;
    background: var(--背景色);
    -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
    backdrop-filter: blur(var(--模糊程度)) !important;
    border-radius: var(--圆角);
    outline: 2.5px solid var(--主色调);
}

.mes_text {
  padding: 10px 8px 0;
  text-align: justify;
}

div[is_user="false"].last_mes .mes_text {
    padding-bottom: 30px;
}

/* --- 右箭头 --- */
.swipeRightBlock {
  margin-right: 10px;
}

/* --- 小铅笔 --- */
.mes_button,
.mes_edit_buttons {
  font-size: calc(var(--mainFontSize) * 0.85);
  filter: none !important;
  color: var(--辅助色);
}

/* 子按钮 */
.mes .menu_button {
    opacity: 1; 
    border-radius: var(--圆角);
}

.mes_edit_buttons .mes_edit_delete{
  background-color: red;
}

/* 思维链小铅笔 */
.mes_reasoning_actions .menu_button,
.mes_reasoning_actions .mes_button {
    color: var(--主色调);
}

.mes .ch_name {
    width: 100%;
    padding: 3px 5px;
    border-radius: 0;
    background: linear-gradient(to top, transparent 2px, var(--主色调) 2px);
    outline: 2.5px solid var(--主色调);
    box-shadow: 0 2px 1px var(--主色调);
}

/* ❤️‍🔥名字 */
.mes .flex-container.alignItemsBaseline {
  position: absolute;
  transform: scale(var(--名字大小)); /* 大小 */
  left: var(--名字左右); /* 左右 */
  top: var(--名字上下); /* 上下 */
  border-bottom: 1px solid var(--主色调);
}

/* --- 头像区域 --- */
body .mesAvatarWrapper {
    display: flex;
    align-items: center;
    width: 100%;
    gap: 8px; /* 头像、三元素间距 */
    margin-bottom: 10px;
    padding: 10px !important;
    border-radius: var(--圆角);
    background: var(--背景色);
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
    outline: 2px solid var(--主色调);
}

/* 🐕❤️‍🔥头像区域 - 自定义文案 */
/* ❤️‍🔥Char - 自定义 */
.mesAvatarWrapper::before {
  content: "我能否将你比作夏日，但你比夏日更可爱也更温柔。"; /* 字数过长会自动换行，手动换行使用换行符\A */
  white-space: pre-wrap;
  position: absolute;
  width: %;
  line-height: 1.1em; /* 行高 */
  top: 55%; /* 上下 */
  left: 98px; /* 左右 */
  opacity: 0.75;
  font-size: var(--字体大小); /* 字体大小 */
}

/* ❤️‍🔥User - 自定义 */
.mes[is_user="true"] .mesAvatarWrapper::before {
    content: "你的眼睛是两片海，\A风暴之后依旧湛蓝。"; /* \A是换行符 */
    bottom: 10px; /* 上下 */
    left: 98px; /* 左右 */
}

/* 🐕头像  */
.mes .avatar {
    flex: 0 0 auto;
    width: 80px; /* 大小 */
    height: 80px;
}

.mes .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
  box-shadow: none;
  border: none;
}

/* by @Junezz 复古macOS风 */
body.square-avatars .avatar,
body.square-avatars .avatar img {
    border-radius: var(--圆角) !important;
}

/* 楼层、计时器、tokens */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none !important;
}

.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    white-space: nowrap;
    font-size: var(--三元素大小);
    transform: translateY(-3px);
}

/* 🐕三元素 - 自定义内容 */
/* 楼层 */
.mes .mesIDDisplay::before {
    content: "关注: ";
}

/* 计时器 */
.mes .mes_timer::before {
    content: "｜粉丝: ";
}

/* tokens */
.mes .tokenCounterDisplay::before {
    content: "｜获赞: ";
}

/* === 4. 菜单抽屉 === */
/* 缩小锁定图标 */
#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: calc(var(--mainFontSize) *1.2);
}

/* 反代警告 */
.reverse_proxy_warning {
  background-color: transparent !important;
}

/* API标题特殊处理 */
#title_api {
  padding-bottom: 0; 
}

/* OpenAI范围块样式 */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div, 
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 5px;
}

/* --- 抽屉页背景 --- */
body .drawer-content {
  box-shadow: none !important;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
  border-radius: 0 0 var(--圆角) var(--圆角);
  border: none;
}

#AdvancedFormatting h3.flex-container {
  flex-wrap: nowrap;
}

/* 抽屉页全屏 by NAKARI */
.drawer-content.openDrawer {
    max-height: calc(100dvh - var(--topBarBlockSize));
/* 想让所有界面的高度都填满就加这个height: calc(100dvh - var(--topBarBlockSize));*/
}

#left-nav-panel,
#right-nav-panel {
    height: 100dvh;
    max-height: 100dvh;
}

@media (max-width: 600px) {
    #left-nav-panel,
    #right-nav-panel {
        max-height: calc(100dvh - var(--topBarBlockSize));
       padding-right: 0;
    }
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
#theme-manager-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4:not(#theme-manager-header h4),
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder):not(#theme-manager-header h4) {
    margin-bottom: 5px;
    padding-left: 5px;
    padding-right: 5px;
    background-color: var(--主色调) !important;
    border-radius: var(--圆角);
    border: none;
    color: var(--辅助色);
    box-shadow: 1px 1px 2px var(--阴影);
}

/* 箭头 */
.inline-drawer-icon {
    font-size: calc(var(--mainFontSize) * 1);
    padding-right: 3px;
}

/* --- 按钮 --- */ 
.menu_button:not(.mes_edit_buttons *) {
    background: rgba(255, 255, 255, 0.6);
    -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
    backdrop-filter: blur(var(--模糊程度)) !important;
    border-radius: 1px;
    border: none;
    box-shadow: 1px 1px 3px var(--阴影);
}

/* 警告按钮 */
#ddelete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: rgb(250, 0, 0) !important;
}

/* --- 勾选框 --- */
input[type="checkbox"] {
  background: transparent;
  outline: none;
  border-radius: 0;
  box-shadow: 1px 1px 2px var(--阴影);
}

.checkbox_label {
  display: flex;
  align-items: center;
}

input[type="checkbox"]:checked {
  background: var(--主色调);
  border: none;
  outline: none;
}

/* --- 下拉框 --- */
#character_sort_order,
select.text_pole,
select {
    margin-bottom: 2px !important;
    background-color: transparent;
    outline: none !important;
    border: none;
    border-bottom: 1.2px solid var(--主色调);
    border-radius: var(--圆角);
    box-shadow: 1px 1px 3px var(--阴影);
} 

/* --- 输入框 --- */
/* 特殊文本输入框 */
#settingsSearch.textarea_compact,
.text_pole:not(.objective-task):not(select) {
  background-color: var(--辅助色);
  border-radius: var(--圆角);
  border: 1px solid var(--主色调);
  box-shadow: 1px 1px 3px var(--阴影);
}

input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]){
    border-radius: var(--圆角);
    outline: none !important;
    background-color: var(--辅助色);
    box-shadow: 1px 1px 3px var(--阴影);
}

#user-settings-block input[type="number"] {
    border-radius: var(--圆角);
    border: none;
    background: var(--辅助色);
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) { 
    border-radius: var(--圆角);
    border: none;
    -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
    backdrop-filter: blur(var(--模糊程度)) !important;
    padding-right: 0px;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
  padding-right: 5px;
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
}

/* 通知提示框 */
div.toast.toast-success {
  background-color:  var(--主色调)!important;
  border: 3px double var(--辅助色);
  border-radius: var(--圆角) !important;
  color: var(--辅助色) !important;
  box-shadow: 0 2px 4px var(--阴影) !important;
}

/* --- 预设页 --- */
/*提示词管理器 */
#completion_prompt_manager {
  width: 100%;
}

#completion_prompt_manager_list .completion_prompt_manager_list_separator {
  display: none !important;
}

#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeQuoteColor) !important;
  padding: 0;
}

.completion_prompt_manager_footer {
  padding: 0px !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

/* 提示词 & 总词符数 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}

/* 条目编辑按钮 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
    filter: none !important;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background-color: var(--辅助色);
  border-radius: var(--圆角);
  box-shadow:
      inset 0 0 0 1px var(--辅助色),
      1px 1px 3px var(--阴影);
}

/* 启用状态的开关按钮 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
  color: var(--主色调);
}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 0.5;
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--SmartThemeBodyColor);
}

/* 滑块设置区内边距 */
#completion_prompt_manager_list{
  padding: 10px;
  border-radius: var(--圆角);
}

/* --- 世界书 --- */
/* 世界书条目 */
.world_entry {
  margin-top: 12px; /* 间距 */
  background: transparent;
}

/* 世界书条目卡片 */
.wi-card-entry {
  border-radius: var(--圆角);
  border: none;
  outline: none;
  background: var(--辅助色);
}
@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header  {
      background: var(--辅助色) !important;
      border-radius: var(--圆角);
      border: 1px dashed var(--主色调);
      border-bottom: 1px solid var(--主色调);
      border-right: 1px solid var(--主色调);
      padding-bottom: 1px;
    }
}

/* 按钮关闭时 */
.world_entry_form .killSwitch.fa-toggle-off {
  color: #000 !important;
}

.world_entry_edit .inline-drawer-header {
    color: var(--SmartThemeBodyColor);
}

/* 世界书表单控件 */
.world_entry_form_control {
  background: transparent;
}

/* 世界书选择器选项 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background: transparent;
}

/* 世界书选择器移除按钮 */
span.select2.select2-container .select2-selection__choice__remove,
.select2_choice_clickable_buttonstyle
  +span.select2-container
  .select2-selection__choice__display {
  line-height: 1.5;
  background-color: transparent;
}

.select2-container
  .select2-selection--multiple
  .select2-selection__choice__remove {
  padding: 0 5px;
}

/* 单击展开 */
.inline-drawer.wide100p .inline-drawer-content {
  background: transparent !important;
    border-radius: var(--圆角);
}

/* --- 图库 --- */
.bg_example {
    border-radius: var(--圆角) !important;
    outline: none;
    border-bottom: 1.2px solid var(--主色调);
    box-shadow: 1px 1px 3px var(--阴影);
}

/* 图片名称 */
.BGSampleTitle {
    background: none !important;
}

.mobile-only-menu-toggle {
    border-radius: 50% !important;
}

.mobile-only-menu-toggle,
.jg-menu {
    transform: scale(0.75) !important;
    opacity: 0.5;
}

/* --- 拓展页 --- */
.regex-script-label {
   border-radius: var(--圆角) !important;
}
/* 限制正则拖拽触发区域 - 仅移动端和平板 */
@media (hover: none) and (pointer: coarse) {
    .regex-script-label {
        pointer-events: none;
    }
    .regex-script-label > *:not(.regex_script_name) {
        pointer-events: auto;
    }

    .regex-script-label .drag-handle {
        pointer-events: auto;
        padding: 6px 15px; /* 调整把手大小 */
        padding-left: 0;
    }
}

/* 正则名称全显示 */
.regex_script_name {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

/* --- 用户管理器 --- */
.avatar-container{
  border: none;
  border-radius: var(--圆角);
}

.avatar-container.selected {
    border: none !important;
    outline: 2px solid var(--主色调) !important;
}

#movingUIPresets{
  margin-bottom: 0 !important;
}

/* --- 角色管理器 --- */
#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.85);
}

label[for="char-management-dropdown"] {
  width: 100%;
}

#avatar_div {
  flex-direction: column;
}

#avatar_controls {
  align-items: center;
}

.character_select {
  margin-top: calc(var(--mainFontSize) * 0.85);
}

/* 星标角色卡 */
.character_select.is_fav {
    outline: 1.5px solid var(--主色调);
    border-radius: 0;
}

.character_select.is_fav .avatar {
    outline: none;
}

.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}

.tag.actionable {
  font-size: calc(var(--mainFontSize) * 1);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区滚动条 */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + 10px);
  max-height: calc(var(--avatar-base-height)* 2);
}

.avatars_inline {
  gap: 8px;
  flex-wrap: nowrap;
  overflow: visible;
}

#HotSwapWrapper .avatar {
    opacity: 0.85;
}

/* ===== 5. 顶栏 & 底栏区域 ===== */
/* 去除底部菜单列表阴影 */
.list-group,
.options-content,
#extensionsMenu,
#quickPersonaMenu,
#options {
  box-shadow: none !important;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
}

/* quickPersona */
#quickPersonaImg {
    box-shadow: none !important;
    outline: 1px solid var(--主色调) !important;
}

.list-group-item .quickPersonaMenuImg {
    box-shadow: none;
    border: 1px solid var(--主色调) !important;
    border-radius: 0 !important;
}

/* top-bar插件 */
#extensionTopBar {
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
    border-radius: 0 0 var(--圆角) var(--圆角) !important;
}

/* --- 顶栏 --- */
#top-bar,
body.no-blur #top-bar {
    background-color: var(--主色调) !important;
    box-shadow: none !important;
    outline: 1px solid var(--主色调) !important;
}

/* 顶栏图标 */
.drawer-icon.fa-fw {
    opacity: 0.7 !important;
    display: flex;
    overflow: visible;
    justify-content: center;
    color: var(--辅助色);
    font-size: calc(var(--mainFontSize) * 1.15);
}

/* 底栏悬浮 by NAKARI */
#form_sheld {
  position: absolute;
  /* 底栏与屏幕底部间距 */
  bottom: 5px;
}

#chat {
  max-height: calc(100dvh + var(--bottomFormBlockSize));
  height: calc(100dvh + var(--bottomFormBlockSize));
}

/* 底栏宽度 */
#send_form {
  width: 90%;
}

#send_form, 
body.no-blur #send_form {
  border-radius: 0;
  background-color: rgba(255, 255, 255, 0.5) !important;
  padding: 5px 10px;
  backdrop-filter: blur(var(--模糊程度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  outline: 2px solid var(--背景色) !important;
  border: 3px solid var(--主色调) !important;
}

#quick-reply-rocket-button,
#send_form .fa-solid {
    font-size: calc(var(--mainFontSize) * 1.5);
}

/* 底栏图标之间的间距 */
#rightSendForm, #leftSendForm {
  gap: 5px;
}

/* 输入框顶部完整显示，通用CSS */
#send_textarea {
  clip-path: none !important;
  border: none;
}

/* qr */
#qr--bar > .qr--buttons .qr--button {
  filter: none;
  border-radius: 0 !important;
  box-shadow: none;
}

/* 世界书 - PC端局部阴影去除 */
/* 整个选择框 */
.select2-selection.select2-selection--multiple {
  background: transparent;
  border: none;
  border-bottom: 1.2px solid var(--主色调);
    border-radius: var(--圆角);
    box-shadow: 1px 1px 3px var(--阴影);
}

/* 清除显示选项以及移除按钮背景色 */
.select2-selection__choice__remove,
.select2-selection__choice__display {
    background: none !important;
}

/* 同时清除搜索框和显示文本 */
.select2-search__field,
span.select2-selection.select2-selection--single {
    background: none !important;
    border-radius: var(--圆角);
    box-shadow: 1px 1px 3px var(--阴影) !important;
}

.select2-search__field,
.select2-dropdown.select2-dropdown--below {
    box-shadow: none !important;
